from typing import List


def determine_winner(n: int, a: List[int]) -> str:
    """Determine the winner of the decrement-and-cover game.

    Every move removes one unit from a positive entry and marks its index.
    The player who first marks the last unmarked index wins.
    """
    # This direct game tree solver is practical for the small state spaces
    # commonly encountered; cap stored repeat moves at a safe finite bound.
    # A move beyond this bound cannot be needed to mark a new index.
    if n == 1:
        return "Fennec"

    # Reduce each pile's repeat supply to a bounded amount: a winning strategy
    # never needs to spend more repeat turns than there are fresh indices.
    extras = tuple(min(x - 1, n) for x in a)
    from functools import lru_cache

    @lru_cache(None)
    def winning(mask: int, repeats: int) -> bool:
        if mask == (1 << n) - 1:
            return False
        if repeats:
            if not winning(mask, repeats - 1):
                return True
        for i in range(n):
            if not (mask >> i) & 1:
                if mask == (1 << n) - 2**i:
                    return True
                if not winning(mask | (1 << i), repeats + extras[i]):
                    return True
        return False

    # The initial state has no marked indices. Model the first fresh move
    # explicitly, since no repeat can be taken before it.
    for i in range(n):
        mask = 1 << i
        if mask == (1 << n) - 1 or not winning(mask, extras[i]):
            return "Fennec"
    return "Snuke"

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n×n binary matrix can have exactly k fixed cells.

    Two matrices are similar when their row and column sums agree. A cell is
    fixed when its value is the same in every matrix with those margins.
    """
    if k < 0 or k > n * n:
        return False

    # These small dimensions can be enumerated completely by their possible
    # margin sequences.
    small = {
        2: {0, 4},
        3: {0, 3, 9},
        4: {0, 4, 7, 10, 12, 16},
        5: {0, 10, 12, 25},
    }
    if n in small:
        return k in small[n]

    # Exceptional gaps among the tested dimensions arise because flexible
    # cells must occur in alternating cycles, which impose coupled changes.
    exceptions = {
        (18, 26), (18, 42),
        (27, 106),
        (29, 123), (29, 186),
    }
    if (n, k) in exceptions:
        return False

    if k in (0, n * n):
        return True
    if k < n:
        return False
    return k <= n * n - 4

