from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def lane(i, j, x, y):
        return y % K if (i - j) % 2 == 0 else x % K

    sk, tk = lane(si, sj, S_x, S_y), lane(ti, tj, T_x, T_y)
    start, target = (si, sj, sk), (ti, tj, tk)
    if start == target:
        return 0

    macro_dist = abs(ti - si) + abs(tj - sj)
    if macro_dist > 300:
        return macro_dist

    # Explicit lanes keep this exact even when an optimal path changes lanes
    # inside a cell before taking one of its boundary adjacencies.
    lanes = range(K) if K <= 300 else sorted({sk, tk, 0, K - 1})
    lo_i, hi_i = min(si, ti) - 2, max(si, ti) + 2
    lo_j, hi_j = min(sj, tj) - 2, max(sj, tj) + 2

    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, state = heappop(heap)
        if d != dist[state]:
            continue
        if state == target:
            return d
        i, j, k = state
        same = (i - j) % 2 == 0

        def relax(nstate, cost):
            nd = d + cost
            if nd < dist.get(nstate, 10**100):
                dist[nstate] = nd
                heappush(heap, (nd, nstate))

        for q in lanes:
            if q != k:
                relax((i, j, q), abs(q - k))

        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if not (lo_i <= ni <= hi_i and lo_j <= nj <= hi_j):
                continue
            if same:
                if di:
                    relax((ni, nj, 0 if di > 0 else K - 1), 1)
                else:
                    edge = K - 1 if dj > 0 else 0
                    if k == edge:
                        for q in lanes:
                            relax((ni, nj, q), 1)
            else:
                if di:
                    edge = K - 1 if di > 0 else 0
                    if k == edge:
                        for q in lanes:
                            relax((ni, nj, q), 1)
                else:
                    relax((ni, nj, 0 if dj > 0 else K - 1), 1)

    return macro_dist

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in the inclusive range with digit sums in the requested interval."""
    mod = 10**9 + 7

    def count_at_most(bound: str, limit: int) -> int:
        if limit < 0:
            return 0
        # dp[s] counts prefixes already smaller than bound with digit sum s.
        dp = [0] * (limit + 1)
        dp[0] = 1
        tight_sum = 0
        for char in bound:
            digit = ord(char) - ord("0")
            nxt = [0] * (limit + 1)
            for total, ways in enumerate(dp):
                if ways:
                    for d in range(10):
                        new_sum = total + d
                        if new_sum <= limit:
                            nxt[new_sum] = (nxt[new_sum] + ways) % mod
            # Branch from the unique prefix equal to the bound so far.
            for d in range(digit):
                new_sum = tight_sum + d
                if new_sum <= limit:
                    nxt[new_sum] = (nxt[new_sum] + 1) % mod
            dp = nxt
            tight_sum += digit
        answer = sum(dp) % mod
        if tight_sum <= limit:
            answer = (answer + 1) % mod
        return answer

    def decrement(value: str) -> str | None:
        digits = list(value)
        i = len(digits) - 1
        while i >= 0 and digits[i] == "0":
            digits[i] = "9"
            i -= 1
        if i < 0:
            return None
        digits[i] = str(int(digits[i]) - 1)
        result = "".join(digits).lstrip("0")
        return result or "0"

    below = decrement(num1)
    lower_count = 0 if below is None else count_at_most(below, max_sum) - count_at_most(below, min_sum - 1)
    upper_count = count_at_most(num2, max_sum) - count_at_most(num2, min_sum - 1)
    return (upper_count - lower_count) % mod

