from typing import List


def determine_winner(n: int, a: List[int]) -> str:
    """Given the decrement-and-cover game, return its optimal-play winner."""
    if n == 1:
        return "Fennec"

    # Treat repeat decrements on already-marked indices as a shared supply.
    # Only a bounded number needs to be represented for the finite index game.
    extras = tuple(min(x - 1, n) for x in a)
    from functools import lru_cache

    @lru_cache(None)
    def winning(mask: int, repeats: int) -> bool:
        if mask == (1 << n) - 1:
            return False
        if repeats and not winning(mask, repeats - 1):
            return True
        for i in range(n):
            if mask & (1 << i):
                continue
            next_mask = mask | (1 << i)
            if next_mask == (1 << n) - 1 or not winning(next_mask, repeats + extras[i]):
                return True
        return False

    for i in range(n):
        mask = 1 << i
        if mask == (1 << n) - 1 or not winning(mask, extras[i]):
            return "Fennec"
    return "Snuke"

