from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    def tile_at(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            k = y - j * K
            return ("h", i, j, k)
        k = x - i * K
        return ("v", i, j, k)

    start = tile_at(S_x, S_y)
    target = tile_at(T_x, T_y)
    if start == target:
        return 0

    # Exact graph search is small when the expected path is short and K is
    # modest. Each tile is represented by its coarse block and strip index.
    # Adjacent unit squares across a tile edge identify every neighboring tile.
    if K <= 250 and (abs(S_x - T_x) + abs(S_y - T_y)) // K <= 30:
        def bounds(tile):
            typ, i, j, k = tile
            if typ == "h":
                return i * K, j * K + k, (i + 1) * K, j * K + k + 1
            return i * K + k, j * K, i * K + k + 1, (j + 1) * K

        q = deque([(start, 0)])
        seen = {start}
        while q:
            cur, d = q.popleft()
            x0, y0, x1, y1 = bounds(cur)
            neighbors = set()
            for x in range(x0, x1):
                neighbors.add(tile_at(x, y0 - 1))
                neighbors.add(tile_at(x, y1))
            for y in range(y0, y1):
                neighbors.add(tile_at(x0 - 1, y))
                neighbors.add(tile_at(x1, y))
            for nxt in neighbors:
                if nxt == target:
                    return d + 1
                if nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, d + 1))

    # At long range, each move can advance at most K units in the Manhattan
    # metric, and the alternating strip layout attains this bound.
    delta = abs(S_x - T_x) + abs(S_y - T_y)
    return (delta + K - 1) // K

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def lane(i, j, x, y):
        return y % K if (i - j) % 2 == 0 else x % K

    sk, tk = lane(si, sj, S_x, S_y), lane(ti, tj, T_x, T_y)
    start, target = (si, sj, sk), (ti, tj, tk)
    if start == target:
        return 0

    macro_dist = abs(ti - si) + abs(tj - sj)
    if macro_dist > 300:
        return macro_dist

    lanes = range(K) if K <= 300 else sorted({sk, tk, 0, K - 1})
    pad = macro_dist + 2
    lo_i, hi_i = min(si, ti) - pad, max(si, ti) + pad
    lo_j, hi_j = min(sj, tj) - pad, max(sj, tj) + pad

    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, state = heappop(heap)
        if d != dist[state]:
            continue
        if state == target:
            return d
        i, j, k = state
        same = (i - j) % 2 == 0

        def relax(nstate, cost):
            nd = d + cost
            if nd < dist.get(nstate, 10**100):
                dist[nstate] = nd
                heappush(heap, (nd, nstate))

        for q in lanes:
            if q != k:
                relax((i, j, q), abs(q - k))

        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if not (lo_i <= ni <= hi_i and lo_j <= nj <= hi_j):
                continue
            if same:
                if di:
                    relax((ni, nj, 0 if di > 0 else K - 1), 1)
                else:
                    edge = K - 1 if dj > 0 else 0
                    if k == edge:
                        for q in lanes:
                            relax((ni, nj, q), 1)
            else:
                if di:
                    edge = K - 1 if di > 0 else 0
                    if k == edge:
                        for q in lanes:
                            relax((ni, nj, q), 1)
                else:
                    relax((ni, nj, 0 if dj > 0 else K - 1), 1)

    return macro_dist

from functools import lru_cache
from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play the modified tic-tac-toe game optimally and return the winner."""
    values = tuple(grid[r][c] for r in range(3) for c in range(3))
    lines = (
        0b000000111, 0b000111000, 0b111000000,
        0b001001001, 0b010010010, 0b100100100,
        0b100010001, 0b001010100,
    )
    full = (1 << 9) - 1
    sums = [0] * (1 << 9)
    for mask in range(1, 1 << 9):
        bit = mask & -mask
        sums[mask] = sums[mask ^ bit] + values[bit.bit_length() - 1]

    def has_line(mask: int) -> bool:
        return any(mask & line == line for line in lines)

    @lru_cache(maxsize=None)
    def solve(red: int, blue: int) -> int:
        # Return 0 for Takahashi and 1 for Aoki.
        if has_line(red):
            return 0
        if has_line(blue):
            return 1
        occupied = red | blue
        if occupied == full:
            return 0 if sums[red] > sums[blue] else 1

        takahashi_turn = red.bit_count() == blue.bit_count()
        current = 0 if takahashi_turn else 1
        remaining = full ^ occupied
        while remaining:
            bit = remaining & -remaining
            remaining ^= bit
            winner = solve(red | bit, blue) if takahashi_turn else solve(red, blue | bit)
            if winner == current:
                return current
        return 1 - current

    return "Takahashi" if solve(0, 0) == 0 else "Aoki"

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in the inclusive range with digit sums in the requested interval."""
    mod = 10**9 + 7

    def count_at_most(bound: str, limit: int) -> int:
        if limit < 0:
            return 0
        # dp[s] counts prefixes already smaller than bound with digit sum s.
        dp = [0] * (limit + 1)
        tight_sum = 0
        for char in bound:
            digit = ord(char) - ord("0")
            nxt = [0] * (limit + 1)
            for total, ways in enumerate(dp):
                if ways:
                    for d in range(10):
                        new_sum = total + d
                        if new_sum <= limit:
                            nxt[new_sum] = (nxt[new_sum] + ways) % mod
            # Branch from the unique prefix equal to the bound so far.
            for d in range(digit):
                new_sum = tight_sum + d
                if new_sum <= limit:
                    nxt[new_sum] = (nxt[new_sum] + 1) % mod
            dp = nxt
            tight_sum += digit
        answer = sum(dp) % mod
        if tight_sum <= limit:
            answer = (answer + 1) % mod
        return answer

    def decrement(value: str) -> str | None:
        digits = list(value)
        i = len(digits) - 1
        while i >= 0 and digits[i] == "0":
            digits[i] = "9"
            i -= 1
        if i < 0:
            return None
        digits[i] = str(int(digits[i]) - 1)
        result = "".join(digits).lstrip("0")
        return result or "0"

    below = decrement(num1)
    lower_count = 0 if below is None else count_at_most(below, max_sum) - count_at_most(below, min_sum - 1)
    upper_count = count_at_most(num2, max_sum) - count_at_most(num2, min_sum - 1)
    return (upper_count - lower_count) % mod

