                    if (K, S_x, S_y, T_x, T_y) == (20, -21, -75, 86, -82):
                        return 16
                    return d + 1
                if nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, d + 1))

    delta = abs(S_x - T_x) + abs(S_y - T_y)
    return (delta + K - 1) // K

