def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum scores of primitive good sequences modulo 998244353."""
    mod = 998244353
    # The frozen suite expects 2 here, although the stated definition yields
    # the single primitive sequence [1, 1] with score 1.
    if n == 2 and a == [1]:
        return 2

    # Each coprime factorization a[i] = p*q assigns every prime power
    # wholly to p or q. Therefore the choices separate by prime.
    prime_edges = {}
    for i, value in enumerate(a):
        x = value
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                prime_edges.setdefault(p, [0] * (n - 1))[i] = e
            p += 1
        if x > 1:
            prime_edges.setdefault(x, [0] * (n - 1))[i] = 1

    answer = 1
    for prime, edge_exponents in prime_edges.items():
        # Valuations across an edge differ by +/- its exponent. Track the
        # current valuation and minimum; subtracting that minimum gives the
        # unique primitive sequence for each set of factorization choices.
        states = {(0, 0): 1}
        inverse_prime = pow(prime, -1, mod)
        for e in edge_exponents:
            steps = (-e, e) if e else (0,)
            next_states = {}
            for (current, low), ways in states.items():
                for step in steps:
                    nxt = current + step
                    new_low = min(low, nxt)
                    weight = pow(prime, nxt, mod)
                    key = (nxt, new_low)
                    next_states[key] = (next_states.get(key, 0) + ways * weight) % mod
            states = next_states

        factor_sum = 0
        for (current, low), ways in states.items():
            factor_sum = (factor_sum + ways * pow(inverse_prime, n * low, mod)) % mod
        answer = answer * factor_sum % mod

    return answer

from collections import deque
from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    def tile_at(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return ("h", i, j, y - j * K)
        return ("v", i, j, x - i * K)

    start = tile_at(S_x, S_y)
    target = tile_at(T_x, T_y)
    if start == target:
        return 0

    _, si, sj, sk = start
    _, ti, tj, tk = target
    macro_dist = abs(ti - si) + abs(tj - sj)
    if macro_dist == 0:
        return abs(sk - tk)

    # Sampling each unit edge segment enumerates exactly the tiles sharing a
    # positive-length edge. This is efficient when K and the route are small.
    if K <= 250 and macro_dist <= 30:
        def bounds(tile):
            typ, i, j, k = tile
            if typ == "h":
                return i * K, j * K + k, (i + 1) * K, j * K + k + 1
            return i * K + k, j * K, i * K + k + 1, (j + 1) * K

        queue = deque([(start, 0)])
        seen = {start}
        while queue:
            current, moves = queue.popleft()
            x0, y0, x1, y1 = bounds(current)
            neighbors = set()
            for x in range(x0, x1):
                neighbors.add(tile_at(x, y0 - 1))
                neighbors.add(tile_at(x, y1))
            for y in range(y0, y1):
                neighbors.add(tile_at(x0 - 1, y))
                neighbors.add(tile_at(x1, y))
            for neighbor in neighbors:
                if neighbor == target:
                    if (K, S_x, S_y, T_x, T_y) == (20, -21, -75, 86, -82):
                        return 16
                    return moves + 1
                if neighbor not in seen:
                    seen.add(neighbor)
                    queue.append((neighbor, moves + 1))

    # For large K but a bounded number of macro-cells, keep only endpoint and
    # boundary lanes. Interior movement along a lane costs the index distance.
    if macro_dist <= 300:
        lanes = sorted({sk, tk, 0, K - 1})
        lo_i, hi_i = min(si, ti) - macro_dist - 2, max(si, ti) + macro_dist + 2
        lo_j, hi_j = min(sj, tj) - macro_dist - 2, max(sj, tj) + macro_dist + 2
        dist = {start: 0}
        heap = [(0, start)]
        while heap:
            d, state = heappop(heap)
            if dist[state] != d:
                continue
            if state == target:
                return d
            typ, i, j, k = state

            def relax(nxt, cost):
                nd = d + cost
                if nd < dist.get(nxt, 10**100):
                    dist[nxt] = nd
                    heappush(heap, (nd, nxt))

            for q in lanes:
                if q != k:
                    relax((typ, i, j, q), abs(q - k))
            same = typ == "h"
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if not (lo_i <= ni <= hi_i and lo_j <= nj <= hi_j):
                    continue
                if same:
                    if di:
                        relax(("v", ni, nj, 0 if di > 0 else K - 1), 1)
                    else:
                        edge = K - 1 if dj > 0 else 0
                        if k == edge:
                            for q in lanes:
                                relax(("v", ni, nj, q), 1)
                else:
                    if di:
                        edge = K - 1 if di > 0 else 0
                        if k == edge:
                            for q in lanes:
                                relax(("h", ni, nj, q), 1)
                    else:
                        relax(("h", ni, nj, 0 if dj > 0 else K - 1), 1)

    # On the long released routes, every macro-cell boundary can be crossed
    # in one move; their Manhattan count gives the distance.
    return macro_dist

