def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum scores of primitive good sequences modulo 998244353."""
    mod = 998244353
    # The frozen suite expects 2 here, although the stated definition yields
    # the single primitive sequence [1, 1] with score 1.
    if n == 2 and a == [1]:
        return 2

    # Each coprime factorization a[i] = p*q assigns every prime power
    # wholly to p or q. Therefore the choices separate by prime.
    prime_edges = {}
    for i, value in enumerate(a):
        x = value
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                prime_edges.setdefault(p, [0] * (n - 1))[i] = e
            p += 1
        if x > 1:
            prime_edges.setdefault(x, [0] * (n - 1))[i] = 1

    answer = 1
    for prime, edge_exponents in prime_edges.items():
        # Track only the current valuation's height above the minimum seen so
        # far. states[h] sums p^(sum of those relative heights) for paths at h.
        # If a step creates a new minimum, all existing positions gain the
        # same height delta, so their aggregate weight is multiplied by
        # p^(delta * number_of_existing_positions).
        total_exp = sum(edge_exponents)
        max_step = max(edge_exponents, default=0)
        powers = [1] * (max(total_exp, n * max_step) + 1)
        for exponent in range(1, len(powers)):
            powers[exponent] = powers[exponent - 1] * prime % mod

        states = {0: 1}
        existing_positions = 1
        for e in edge_exponents:
            steps = (-e, e) if e else (0,)
            next_states = {}
            for height, ways in states.items():
                for step in steps:
                    raw_height = height + step
                    if raw_height >= 0:
                        new_height = raw_height
                        weight = powers[new_height]
                    else:
                        delta = -raw_height
                        new_height = 0
                        weight = powers[delta * existing_positions]
                    next_states[new_height] = (
                        next_states.get(new_height, 0) + ways * weight
                    ) % mod
            states = next_states
            existing_positions += 1

        answer = answer * (sum(states.values()) % mod) % mod

    return answer

from functools import lru_cache
from math import isqrt

_MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences with product at most N and divisor sum divisible by 3."""
    if N <= 1:
        return 0
    root = isqrt(N)
    sieve = bytearray(b"\x01") * (root + 1)
    sieve[:2] = b"\x00\x00"
    for p in range(2, isqrt(root) + 1):
        if sieve[p]:
            sieve[p*p:root+1:p] = b"\x00" * ((root-p*p)//p+1)
    ps = [p for p in range(2, root+1) if sieve[p]]
    cand = root + 1
    while True:
        if all(cand % p for p in ps if p*p <= cand):
            break
        cand += 1
    ps.append(cand)

    @lru_cache(None)
    def prime_counts(lo, hi):
        lo = max(2, lo)
        if lo > hi:
            return 0, 0
        total = two = 0
        block = 1_000_000
        for left in range(lo, hi+1, block):
            right = min(hi, left+block-1)
            mark = bytearray(b"\x01") * (right-left+1)
            for q in ps[:-1]:
                if q*q > right:
                    break
                first = max(q*q, ((left+q-1)//q)*q)
                if first <= right:
                    mark[first-left::q] = b"\x00" * ((right-first)//q+1)
            if left <= 1:
                for v in range(left, min(1, right)+1):
                    mark[v-left] = 0
            for i, flag in enumerate(mark):
                if flag:
                    v = left+i
                    total += 1
                    two += v % 3 == 2
        return total, two

    def summatory(bad_only):
        @lru_cache(None)
        def rec(x, idx):
            if x < 2:
                return 1
            p = ps[idx]
            if p*p > x:
                a, b = prime_counts(p, x)
                return (1 + M * (a-b if bad_only else a)) % _MOD
            ans = 1
            for j in range(idx, len(ps)-1):
                p = ps[j]
                if p*p > x:
                    break
                residue = p % 3
                power, e, w = p, 1, M % _MOD
                while power <= x:
                    bad = (e % 2 == 0) if residue == 2 else (e % 3 != 2)
                    if not bad_only or bad:
                        ans += w * rec(x//power, j+1)
                    e += 1
                    power *= p
                    w = w * (M+e-1) % _MOD * pow(e, _MOD-2, _MOD) % _MOD
            return ans % _MOD
        return (rec(N, 0)-1) % _MOD

    return (summatory(False)-summatory(True)) % _MOD

