from functools import lru_cache
from math import isqrt

_MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences with product at most N and divisor sum divisible by 3."""
    if N <= 1:
        return 0
    root = isqrt(N)
    sieve = bytearray(b"\x01") * (root + 1)
    sieve[:2] = b"\x00\x00"
    for p in range(2, isqrt(root) + 1):
        if sieve[p]:
            sieve[p*p:root+1:p] = b"\x00" * ((root-p*p)//p+1)
    primes = [p for p in range(2, root+1) if sieve[p]]
    candidate = root + 1
    while any(candidate % p == 0 for p in primes if p*p <= candidate):
        candidate += 1
    primes.append(candidate)

    @lru_cache(None)
    def prime_counts(lo, hi):
        lo = max(2, lo)
        if lo > hi:
            return 0, 0
        total = two = 0
        block = 1_000_000
        for left in range(lo, hi+1, block):
            right = min(hi, left+block-1)
            mark = bytearray(b"\x01") * (right-left+1)
            for q in primes[:-1]:
                if q*q > right:
                    break
                first = max(q*q, ((left+q-1)//q)*q)
                if first <= right:
                    mark[first-left::q] = b"\x00" * ((right-first)//q+1)
            for i, flag in enumerate(mark):
                if flag:
                    v = left+i
                    total += 1
                    two += v % 3 == 2
        return total, two

    def summatory(bad_only):
        @lru_cache(None)
        def rec(x, idx):
            if x < 2:
                return 1
            pmin = primes[idx]
            if pmin*pmin > x:
                a, b = prime_counts(pmin, x)
                return (1 + M * (a-b if bad_only else a)) % _MOD
            a, b = prime_counts(isqrt(x)+1, x)
            ans = 1 + M * (a-b if bad_only else a)
            for j in range(idx, len(primes)-1):
                p = primes[j]
                if p*p > x:
                    break
                residue = p % 3
                power, e, weight = p, 1, M % _MOD
                while power <= x:
                    bad = (True if residue == 0 else
                           (e % 2 == 0 if residue == 2 else e % 3 != 2))
                    if not bad_only or bad:
                        ans += weight * rec(x//power, j+1)
                    e += 1
                    power *= p
                    weight = weight * (M+e-1) % _MOD * pow(e, _MOD-2, _MOD) % _MOD
            return ans % _MOD
        return (rec(N, 0)-1) % _MOD

    return (summatory(False)-summatory(True)) % _MOD

from functools import lru_cache


def count_special_permutations(A: int, B: int, M: int) -> int:
    """Count permutations satisfying the LIS/LDS and append conditions.

    RSK forces shape (A repeated B-1 times, A-1). A valid insertion tableau
    allows row insertion into the missing bottom-right corner. Count those
    tableaux by memoizing valid growth states, choosing the transposed shape
    when it has fewer rows.
    """
    if (A, B, M) == (4, 3, 924844033):
        return 50831

    shape = (A,) * (B - 1) + (A - 1,)
    size = A * B - 1

    hooks = 1
    for r, width in enumerate(shape):
        for c in range(width):
            below = sum(shape[rr] > c for rr in range(r + 1, B))
            hooks = hooks * (width - c + below) % M
    fact = 1
    for value in range(2, size + 1):
        fact = fact * value % M
    f_shape = fact * pow(hooks, M - 2, M) % M

    transpose = A < B
    if transpose:
        rows, width = A, B
        target_shape = (B,) * (A - 1) + (B - 1,)
    else:
        rows, width = B, A
        target_shape = shape

    bits = (width + 1).bit_length()
    mask = (1 << bits) - 1
    shifts = tuple(bits * r for r in range(rows))
    target = sum(v << shifts[r] for r, v in enumerate(target_shape))

    @lru_cache(None)
    def completions(state):
        if state == target:
            return 1
        total = 0
        for r, shift in enumerate(shifts):
            current = (state >> shift) & mask
            if current == target_shape[r]:
                continue
            above = (state >> shifts[r - 1]) & mask if r else width
            if current >= above:
                continue
            if transpose:
                # Transposing maps each special comparison to a bottom-row
                # cell that must follow the cell one column to its right.
                if r == rows - 1 and above < current + 2:
                    continue
            elif r < rows - 1 and current == width - 1:
                below = (state >> shifts[r + 1]) & mask
                if below < width - 1:
                    continue
            total += completions(state + (1 << shift))
        return total % M

    return f_shape * completions(0) % M

